final class Fenwick {
    private final long[] tree;
    Fenwick(int n) { tree = new long[n + 1]; }

    void add(int index, long delta) {           // index is 0-based
        for (int i = index + 1; i < tree.length; i += i & -i) tree[i] += delta;
    }

    long prefixSum(int endExclusive) {          // sum of [0, endExclusive)
        long sum = 0;
        for (int i = endExclusive; i > 0; i -= i & -i) sum += tree[i];
        return sum;
    }

    long rangeSum(int from, int toExclusive) {
        return prefixSum(toExclusive) - prefixSum(from);
    }
}

