static int[] prefixFunction(String p) {
    int[] border = new int[p.length()];
    for (int i = 1, k = 0; i < p.length(); i++) {
        while (k > 0 && p.charAt(i) != p.charAt(k)) k = border[k - 1];
        if (p.charAt(i) == p.charAt(k)) k++;
        border[i] = k;
    }
    return border;
}

static int indexOf(String text, String p) {
    if (p.isEmpty()) return 0;
    int[] border = prefixFunction(p);
    for (int i = 0, k = 0; i < text.length(); i++) {
        while (k > 0 && text.charAt(i) != p.charAt(k)) k = border[k - 1];
        if (text.charAt(i) == p.charAt(k)) k++;
        if (k == p.length()) return i - k + 1;
    }
    return -1;
}

