@Service
class PaymentEventsConsumer {
    private final ProcessedMessageRepository processed;
    private final LedgerService ledger;

    PaymentEventsConsumer(ProcessedMessageRepository processed, LedgerService ledger) {
        this.processed = processed;
        this.ledger = ledger;
    }

    @KafkaListener(topics = "payments")
    @Transactional
    public void onPayment(PaymentCaptured event) {
        // Unique key on message_id: a duplicate insert fails and rolls back the whole effect.
        if (!processed.tryInsert(event.messageId())) return;
        ledger.credit(event.accountId(), event.amountCents());
    }
}

