interface Channel { String name(); SendResult send(Recipient to, Rendered message); }
interface Policy { Optional<Instant> deferUntil(Notification n, Instant now); }

final class Dispatcher {
    private final Map<String, Channel> channels;
    private final List<Policy> policies;
    private final TemplateRenderer renderer;
    private final AttemptStore attempts;

    Dispatcher(Map<String, Channel> channels, List<Policy> policies,
               TemplateRenderer renderer, AttemptStore attempts) {
        this.channels = Map.copyOf(channels);
        this.policies = List.copyOf(policies);
        this.renderer = renderer;
        this.attempts = attempts;
    }

    void dispatch(Notification n, Instant now) {
        if (!attempts.claim(n.idempotencyKey())) return;          // already handled
        for (Policy p : policies) {
            Optional<Instant> later = p.deferUntil(n, now);
            if (later.isPresent()) { attempts.reschedule(n, later.get()); return; }
        }
        Channel channel = channels.get(n.channel());
        SendResult result = channel.send(n.recipient(), renderer.render(n));
        attempts.record(n, result);                                // state machine transition
    }
}
